withinTransaction(async () => {
  const tracks = song.tracks;
  const clipLength = 32; // 8 bars at 4 beats/bar

  // Create initial clips for Drums, Bass, Chords, Pads
  await tracks[1].createMidiClip(0, clipLength); // Drums
  await tracks[2].createMidiClip(0, clipLength); // Bass
  await tracks[3].createMidiClip(0, clipLength); // Chords
  await tracks[4].createMidiClip(0, clipLength); // Pads
});

